
-- Migration 041: Wipe legacy tasks and seed 365 family tasks
-- Generates a full year of tasks for daily earning loops

-- 1. DELETE ALL LEGACY MISSIONS TO START FRESH
DELETE FROM odyssey_mission_definitions;
DELETE FROM odyssey_course_definitions;

-- 2. RE-INSERT JOURNEYS AND COURSES FOR FAMILY APP
ON CONFLICT (slug) DO UPDATE SET 
